alter table public.conversations add column if not exists metadata jsonb not null default '{}'::jsonb;
create or replace function public.start_team_call(p_team_id uuid,p_call_type text default 'video') returns uuid language plpgsql security invoker set search_path=public,private as $$ declare v_me uuid:=auth.uid();v_company uuid;v_call uuid;v_conversation uuid;v_team_name text; begin if v_me is null or p_call_type not in('audio','video') then raise exception 'Invalid request'; end if; select company_id,name into v_company,v_team_name from public.teams where id=p_team_id; if v_company is null or not private.is_company_member(v_company,v_me) then raise exception 'Not authorized'; end if; select c.id into v_conversation from public.conversations c where c.company_id=v_company and c.kind='team' and (c.metadata->>'team_id')=p_team_id::text limit 1; if v_conversation is null then insert into public.conversations(company_id,kind,title,created_by,metadata) values(v_company,'team',v_team_name,v_me,jsonb_build_object('team_id',p_team_id)) returning id into v_conversation; end if; insert into public.conversation_members(conversation_id,user_id,role) select v_conversation,user_id,case when user_id=v_me then 'owner' else 'member' end from public.team_members where team_id=p_team_id on conflict do nothing; insert into public.calls(company_id,conversation_id,team_id,initiator_id,call_type,status,started_at,metadata) values(v_company,v_conversation,p_team_id,v_me,p_call_type,'ringing',now(),jsonb_build_object('team_id',p_team_id)) returning id into v_call; insert into public.call_participants_v2(call_id,user_id,role,status) select v_call,user_id,case when user_id=v_me then 'initiator' else 'participant' end,case when user_id=v_me then 'connected' else 'ringing' end from public.conversation_members where conversation_id=v_conversation; return v_call; end; $$;
grant execute on function public.start_team_call(uuid,text) to authenticated;
